<?php
declare(strict_types=1);

require_once __DIR__.'/includes/init.php';
require_once __DIR__.'/csrf_helper.php';
require_once __DIR__.'/includes/shop_checkout.php';

if(!isset($_SESSION['trener_id'])||!roleAtLeast('admin')){header('Location: login.php');exit;}

function orderAdminH(mixed $value):string{return htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function orderAdminMoney(int $minor,string $currency):string{return number_format($minor/100,2,',',' ').' '.orderAdminH($currency);}
function orderAdminStatusLabel(string $status):string{return ['placed'=>'Vytvořená objednávka','processing'=>'Připravuje se','ready'=>'Připraveno','completed'=>'Vydáno','cancelled'=>'Stornováno'][$status]??$status;}
function orderAdminPaymentLabel(string $status):string{return ['pending'=>'Čeká','paid'=>'Zaplaceno','cancelled'=>'Zrušeno','refund_required'=>'Čeká na vrácení hospodářem','refunded'=>'Vráceno'][$status]??$status;}
function orderAdminActionLabel(?string $action):string{return ['place'=>'Objednávka vytvořena','checkout_created'=>'Objednávka vytvořena','confirm_bank_payment'=>'Bankovní platba potvrzena','confirm_cash_payment'=>'Hotovost přijata','mark_ready'=>'Příprava dokončena','complete_pickup'=>'Osobní výdej potvrzen','dispatch_ppl'=>'Zásilka předána PPL','prepare_packeta'=>'Údaje štítku Zásilkovny uloženy','correct_packeta'=>'Údaje štítku Zásilkovny opraveny','deposit_packeta'=>'Zásilka podána do Z-BOXu','cancel'=>'Objednávka stornována','confirm_refund'=>'Vrácení platby potvrzeno','expire'=>'Nezaplacená objednávka expirována','set_customer_status'=>'Zákaznický stav změněn'][$action??'']??'Záznam změny';}

$query=trim((string)($_GET['q']??''));
$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!csrf_verify((string)($_POST['csrf_token']??''))){
        $errors[]='Formulář vypršel. Obnovte stránku.';
    }else{
        try{
            $action=(string)($_POST['action']??'');$actor=(int)$_SESSION['trener_id'];$reason=(string)($_POST['reason']??'');$confirmed=($_POST['confirm_action']??'')==='1';
            if($action==='customer_status'){
                $result=shopOrderCustomerStatusAssign($pdo,(int)($_POST['order_id']??0),(int)($_POST['customer_status_id']??0),$actor,'Ruční změna zákaznického stavu v administraci.');
                $message=$result['changed']?($result['notification_id']!==null?'Stav změněn; e-mail je ve frontě.':'Stav změněn bez e-mailu.'):'Stav se nezměnil; e-mail se znovu nezařadil.';
            }elseif($action==='cancel'){
                $result=shopOrderAdminCancel($pdo,(int)($_POST['order_id']??0),$actor,$reason,$confirmed,($_POST['packeta_cancelled']??'')==='1');
                if(!$result['changed'])$message='Objednávka už byla stornována.';
                elseif($result['payment_status']==='refund_required')$message='Objednávka byla stornována a sklad vrácen. Přijatou platbu je nutné samostatně vrátit zákazníkovi.';
                else $message='Objednávka byla stornována, platební předpis zrušen a sklad vrácen.';
            }elseif($action==='ready'){
                $result=shopOrderAdminMarkReady($pdo,(int)($_POST['order_id']??0),$actor,$reason,$confirmed);
                $message=$result['changed']?'Objednávka je připravena k předání.':'Objednávka už je připravena.';
            }elseif($action==='complete'){
                $result=shopOrderAdminCompletePickup($pdo,(int)($_POST['order_id']??0),$actor,$reason,$confirmed);
                $message=$result['changed']?'Výdej byl potvrzen a objednávka dokončena.':'Objednávka už byla vydána.';
            }elseif($action==='dispatch_ppl'){
                $result=shopOrderAdminDispatchPpl($pdo,(int)($_POST['order_id']??0),$actor,(string)($_POST['tracking_number']??''),$reason,$confirmed);
                $message=$result['changed']?'Předání PPL je zaznamenáno a číslo zásilky je viditelné zákazníkovi.':'Předání PPL již bylo zaznamenáno.';
            }elseif(in_array($action,['prepare_packeta','correct_packeta'],true)){
                $result=shopOrderAdminPreparePacketa($pdo,(int)($_POST['order_id']??0),$actor,(string)($_POST['tracking_number']??''),(string)($_POST['consignment_code']??''),$reason,$confirmed,$action==='correct_packeta');
                $message='Štítek byl zaznamenán. Po skutečném vložení zásilky do Z-BOXu potvrďte podání.';
            }elseif($action==='deposit_packeta'){
                $result=shopOrderAdminDepositPacketa($pdo,(int)($_POST['order_id']??0),$actor,$reason,$confirmed);
                $message=$result['changed']?'Podání do Z-BOXu je zaznamenáno a zákazník dostane sledovací údaje.':'Podání už bylo zaznamenáno.';
            }else{
                throw new InvalidArgumentException('Neznámá akce objednávky.');
            }
            $_SESSION['flash_order_admin']=$message;
            $target='eshop_orders_admin.php'.($query!==''?'?q='.rawurlencode($query):'').'#order-'.(int)$result['order_id'];
            header('Location: '.$target,true,303);exit;
        }catch(PDOException $exception){
            error_log('eshop_orders_admin.php: '.$exception->getMessage());$errors[]='Databázová operace selhala bez částečného zápisu.';
        }catch(InvalidArgumentException|ShopCheckoutException|ShopOrderCustomerStatusException $exception){
            $errors[]=$exception->getMessage();
        }
    }
}
$success=(string)($_SESSION['flash_order_admin']??'');unset($_SESSION['flash_order_admin']);$orders=shopOrderAdminList($pdo,200,$query);$orderItems=shopOrderAdminItemMap($pdo,array_column($orders,'id'));$customerStatuses=shopOrderCustomerStatusDefinitions($pdo);
?>
